<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class AccountsController extends Controller {
 private function school(){ $u=auth()->user(); abort_unless($u->status && $u->school_id,403); return $u->school_id; }
 private function table($name){return DB::table($name)->where($name.'.school_id',$this->school());}
 private function years(){return $this->table('academic_years')->orderByDesc('start_date')->get();}
 private function filters(Request $r){$years=$this->years();$r->validate(['academic_year_id'=>'nullable|integer','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from']);$year=$r->academic_year_id?$years->firstWhere('id',(int)$r->academic_year_id):($years->firstWhere('is_current',1)??$years->first());abort_unless($year,422,'Select a valid school academic year.');$from=$r->from??$year->start_date;$to=$r->to??$year->end_date;abort_if($from>$to,422);return compact('years','year','from','to');}
 public function index(Request $r){extract($this->filters($r));$income=$this->table('fee_collections')->where('academic_year_id',$year->id)->where('status','posted')->whereBetween('payment_date',[$from,$to])->sum('total_amount');$expenses=$this->table('account_expenses')->where('academic_year_id',$year->id);$pending=(clone $expenses)->whereIn('status',['pending','approved'])->whereBetween('expense_date',[$from,$to])->sum('amount');$payments=$this->table('account_expense_payments')->join('account_expenses as e','e.id','=','account_expense_payments.expense_id')->where('e.school_id',$this->school())->where('e.academic_year_id',$year->id)->whereBetween('payment_date',[$from,$to]);$paid=(clone $payments)->sum('account_expense_payments.amount');$heads=(clone $payments)->join('account_expense_categories as c','c.id','=','e.category_id')->where('c.school_id',$this->school())->groupBy('c.name')->selectRaw('c.name, SUM(account_expense_payments.amount) as total')->get();$recent=(clone $payments)->select('account_expense_payments.*','e.payee')->orderByDesc('payment_date')->orderByDesc('account_expense_payments.id')->limit(8)->get();$vp=$this->table('account_vendor_payments')->join('account_vendor_invoices as vi','vi.id','=','account_vendor_payments.invoice_id')->where('vi.school_id',$this->school())->where('vi.academic_year_id',$year->id);$vendorPaid=(clone $vp)->whereBetween('payment_date',[$from,$to])->sum('account_vendor_payments.amount');$vendorDue=$this->table('account_vendor_invoices')->where('academic_year_id',$year->id)->whereIn('status',['approved','partial','paid'])->sum('amount')-(clone $vp)->sum('account_vendor_payments.amount');$salaryPaid=$this->table('account_salary_payments')->whereBetween('payment_date',[$from,$to])->sum('amount');return view('accounts.dashboard',compact('salaryPaid','vendorPaid','vendorDue','years','year','from','to','income','pending','paid','heads','recent'));}
 public function categories(){return view('accounts.categories',['categories'=>$this->table('account_expense_categories')->orderBy('name')->get()]);}
 public function categoryStore(Request $r){$v=$r->validate(['name'=>['required','string','max:150',Rule::unique('account_expense_categories')->where('school_id',$this->school())]]);DB::table('account_expense_categories')->insert($v+['school_id'=>$this->school(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Category added.');}
 public function expenses(Request $r){extract($this->filters($r));$categories=$this->table('account_expense_categories')->where('active',1)->orderBy('name')->get();$rows=$this->table('account_expenses')->join('account_expense_categories as c','c.id','=','account_expenses.category_id')->where('c.school_id',$this->school())->where('academic_year_id',$year->id)->whereBetween('expense_date',[$from,$to])->select('account_expenses.*','c.name as category')->orderByDesc('account_expenses.id')->paginate(20)->withQueryString();return view('accounts.expenses',compact('years','year','from','to','categories','rows'));}
 public function store(Request $r){$v=$r->validate(['academic_year_id'=>['required',Rule::exists('academic_years','id')->where('school_id',$this->school())],'category_id'=>['required',Rule::exists('account_expense_categories','id')->where('school_id',$this->school())->where('active',1)],'expense_date'=>'required|date_format:Y-m-d|before_or_equal:today','payee'=>'required|string|max:255','amount'=>'required|numeric|decimal:0,2|min:0.01|max:9999999999.99','description'=>'required|string|max:4000','invoice_reference'=>'nullable|string|max:255']);$year=$this->years()->firstWhere('id',(int)$v['academic_year_id']);abort_unless($year && $v['expense_date'] >= $year->start_date && $v['expense_date'] <= $year->end_date,422,'Expense date must fall in selected academic year.');DB::table('account_expenses')->insert($v+['school_id'=>$this->school(),'created_by'=>auth()->id(),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Expense submitted for approval.');}
 public function review(Request $r,$id){$v=$r->validate(['decision'=>'required|in:approved,rejected','review_note'=>'required_if:decision,rejected|nullable|string|max:2000']);DB::transaction(function()use($v,$id){$e=$this->table('account_expenses')->where('id',$id)->lockForUpdate()->first();abort_unless($e,404);abort_unless($e->status==='pending' && $e->created_by!=auth()->id(),422,'Only another authorized user can review a pending expense.');$this->table('account_expenses')->where('id',$id)->update(['status'=>$v['decision'],'review_note'=>$v['review_note']??null,'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Review saved.');}
 public function pay(Request $r,$id){$v=$r->validate(['payment_date'=>'required|date_format:Y-m-d|before_or_equal:today','payment_mode'=>'required|in:cash,upi,bank_transfer,cheque,card,other','reference'=>'required_unless:payment_mode,cash|nullable|string|max:255']);DB::transaction(function()use($v,$id){$e=$this->table('account_expenses')->where('id',$id)->lockForUpdate()->first();abort_unless($e,404);abort_unless($e->status==='approved' && $v['payment_date'] >= $e->expense_date,422,'Expense must be approved and payment cannot precede expense.');DB::table('account_expense_payments')->insert($v+['school_id'=>$this->school(),'expense_id'=>$e->id,'amount'=>$e->amount,'paid_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);$this->table('account_expenses')->where('id',$id)->update(['status'=>'paid','updated_at'=>now()]);});return back()->with('success','Payment recorded.');}
 public function voucher($id){$expense=$this->table('account_expenses')->where('id',$id)->first();abort_unless($expense,404);$payment=$this->table('account_expense_payments')->where('expense_id',$id)->first();abort_unless($payment,404);$school=DB::table('schools')->where('id',$this->school())->first();return view('accounts.voucher',compact('expense','payment','school'));}
}
